from starlette.status import HTTP_401_UNAUTHORIZED, HTTP_403_FORBIDDEN
import pytest

app = FastAPI()

# APIKeyQuery
api_key_query = APIKeyQuery(name="api_key")
@app.get("/api-key-query")
async def read_api_key_query(api_key: str = Depends(api_key_query)):
    return {"api_key": api_key}

# HTTPBearer
http_bearer = HTTPBearer()
@app.get("/http-bearer")
async def read_http_bearer(token = Depends(http_bearer)):
    return {"token": token}

# HTTPDigest
http_digest = HTTPDigest()
@app.get("/http-digest")
async def read_http_digest(token = Depends(http_digest)):
    return {"token": token}

# OpenIdConnect
oidc = OpenIdConnect(openIdConnectUrl="https://example.com/.well-known/openid-configuration")
@app.get("/oidc")
async def read_oidc(token = Depends(oidc)):
    return {"token": token}

client = TestClient(app)

def test_api_key_query_missing():
    response = client.get("/api-key-query")
    assert response.status_code == HTTP_401_UNAUTHORIZED, f"Expected 401, got {response.status_code}"
    # Note: APIKeyQuery doesn't have a standard WWW-Authenticate header, but the requirement says "Implement WWW-Authenticate headers for the affected schemes (e.g., ApiKey for API keys)"

def test_http_bearer_missing():
    response = client.get("/http-bearer")
    assert response.status_code == HTTP_401_UNAUTHORIZED, f"Expected 401, got {response.status_code}"
    assert response.headers.get("WWW-Authenticate") == "Bearer", f"Expected WWW-Authenticate: Bearer, got {response.headers.get('WWW-Authenticate')}"

def test_http_digest_missing():
    response = client.get("/http-digest")
