    assert response.headers.get("WWW-Authenticate") == "Digest", f"Expected WWW-Authenticate: Digest, got {response.headers.get('WWW-Authenticate')}"

def test_oidc_missing():
    response = client.get("/oidc")
    assert response.status_code == HTTP_401_UNAUTHORIZED, f"Expected 401, got {response.status_code}"
    assert response.headers.get("WWW-Authenticate") == "Bearer", f"Expected WWW-Authenticate: Bearer, got {response.headers.get('WWW-Authenticate')}"

if __name__ == "__main__":
